function companionRoleScreenTimeText(c){if(!companionRoleReadsExternal(c,'screenTime'))return '';const st=companionRoleDataState();if(!st||!st.screenTimeAvailable)return '';const apps=Array.isArray(st.apps)?st.apps:[],rows=st.screenTimeMode==='per_app'?apps.map(x=>x.name+'：实际使用 '+companionDuration(x.usedSec||0)).join('；'):'';const stamps=['数据日期 '+(st.usageDay||'未知'),st.usageGeneratedAt?'设备采集 '+fmtDT(st.usageGeneratedAt):'',st.readSessionId?'本次读取 '+st.readSessionId.slice(0,8):''].filter(Boolean).join('，');return '这台真实 iPhone 今日总屏幕使用 '+companionDuration(st.screenTimeSec||0)+(rows?'；逐 App 实际使用：'+rows:'；逐 App 数据尚未同步')+(stamps?'；'+stamps:'');}
